pcall(function()
    if isfile and isfile(CONFIG_PATH) then
        local raw = readfile(CONFIG_PATH)
        if raw and raw ~= "" then LoadedCfg = S.HttpService:JSONDecode(raw) end
    end
end)
if type(LoadedCfg) ~= "table" then LoadedCfg = {} end

local function isDevMode()
    return DEV_MODE == true or (_G.DHubDev == true) or (_G.DEV_MODE == true) or (_G.DevMode == true)
end

local function getEnvKey()
    local g = type(getgenv)=="function" and getgenv() or _G
    return g.key or g.Key or _G.key or _G.Key
end

local function checkKey(k)
    if isDevMode() then return true end
    if not k or k=="" then return false end
    local ok, res = pcall(function() return game:HttpGet(FIREBASE_URL) end)
    if not ok or type(res)~="string" or res=="" then return false end
    local okJ, data = pcall(function() return S.HttpService:JSONDecode(res) end)
    if okJ and type(data)=="table" then
        for ky, v in pairs(data) do
            if tostring(ky)==k or tostring(v)==k then return true end
            if type(v)=="table" and (tostring(v.key)==k or tostring(v.Key)==k or tostring(v.code)==k) then return true end
        end
    else
        if res:find(k, 1, true) then return true end
    end
    return false
end

