    LP.Idled:Connect(function()
        silenceIdle()
        pcall(function()
            local cam = workspace.CurrentCamera
            if cam then
                local cf = cam.CFrame
                cam.CFrame = cf * CFrame.Angles(0, 0.001, 0)
                task.wait(0.1)
                cam.CFrame = cf
            end
        end)
    end)
end

