-- [8] INTEGRITY BYPASS
local function setupIntegrity()
    local function fireReady()
        pcall(function() if RMT.IntReady then RMT.IntReady:FireServer() end end)
    end
    fireReady()
    if RMT.IntHeartbeat then
        RMT.IntHeartbeat.OnClientEvent:Connect(function(...)
            local a = table.pack(...)
            task.delay(math.random()*0.05, function()
                pcall(function()
                    if RMT.IntSync then RMT.IntSync:InvokeServer(table.unpack(a,1,a.n)) end
                end)
            end)
        end)
    end
    if RMT.IntViolation then RMT.IntViolation.OnClientEvent:Connect(function() end) end
    LP.CharacterAdded:Connect(function() task.wait(0.5); fireReady() end)
end
setupIntegrity()

-- [9] CHARACTER UTILITIES & STATUS HELPER
local Runtime = {
    rootPart      = nil,
    humanoid      = nil,
    farming       = false,
    isAutoWalking = false,
    steals             = 0,
    statusText         = "Idle",
    StatusLbl          = nil,
    carryEscapeActive  = false,
}

local bypassDone = false

local function UpdateStatus(txt)
    Runtime.statusText = txt
    if Runtime.StatusLbl then
        Runtime.StatusLbl.Text = string.format("Status: %s  |  Steals: %d", Runtime.statusText, Runtime.steals)
    end
end

local function getChar() return LP.Character end

local function getRoot()
    if Runtime.rootPart and Runtime.rootPart.Parent then return Runtime.rootPart end
    local char = getChar()
    if char then Runtime.rootPart = char:FindFirstChild("HumanoidRootPart") end
    return Runtime.rootPart
end

local function getHumanoid()
    local char = getChar()
    return char and char:FindFirstChildOfClass("Humanoid")
end

local function applyBacBypass(char)
    if not char then return end
    if bypassDone then return end
    local h = char:FindFirstChildOfClass("Humanoid")
    if not h then return end
    local cam  = workspace.CurrentCamera
    local anim = char:FindFirstChild("Animate")
    local ws, jp, jh, hp, mhp = h.WalkSpeed, h.JumpPower, h.JumpHeight, h.Health, h.MaxHealth

    if anim and anim:IsA("LocalScript") then anim.Disabled = true end
    local animator = h:FindFirstChildOfClass("Animator")
    if animator then
        for _, t in ipairs(animator:GetPlayingAnimationTracks()) do t:Stop(0) end
    end

    h.Archivable = true
    local clone = h:Clone()
    for _, c in ipairs(clone:GetChildren()) do if c:IsA("Animator") then c:Destroy() end end

    h.Name = "_OldHumanoid"; clone.Name = "Humanoid"; clone.Parent = char
    Instance.new("Animator").Parent = clone
    clone.WalkSpeed = ws; clone.JumpPower = jp; clone.JumpHeight = jh
    clone.MaxHealth = mhp; clone.Health = math.min(hp, mhp)

    if cam then cam.CameraSubject = clone end
    h:Destroy()

    if anim and anim:IsA("LocalScript") then
        task.wait()
        anim.Disabled = false
        task.defer(function()
            if anim.Parent then anim.Disabled = true; task.wait(); anim.Disabled = false end
        end)
    end
    task.defer(function() if clone.Parent then clone:ChangeState(Enum.HumanoidStateType.Running) end end)
    bypassDone = true
    return clone
end

local function ensureCharacter(timeout)
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if char and root and hum and root.Parent and hum.Health > 0 then
        Runtime.rootPart = root
        return char, root, hum
    end

    timeout = timeout or 8
    local start = tick()
    while (not char or not root or not hum or not root.Parent or hum.Health <= 0) and (tick() - start < timeout) do
        task.wait(0.1)
        char = LP.Character
        root = char and char:FindFirstChild("HumanoidRootPart")
        hum  = char and char:FindFirstChildOfClass("Humanoid")
    end
    if root then Runtime.rootPart = root end
    return char, root, hum
end

local doFarmLoop -- forward declaration

local function bindChar(char)
    if not char then Runtime.rootPart = nil; return end
    Runtime.rootPart = char:WaitForChild("HumanoidRootPart", 5)
    task.spawn(function() pcall(applyBacBypass, char) end)
end

if LP.Character then bindChar(LP.Character) end
LP.CharacterAdded:Connect(function(char)
    Runtime.rootPart = nil
    bypassDone = false
    task.spawn(function()
        local c, r, h = ensureCharacter(10)
        bindChar(c)
        task.wait(0.5)
        if Cfg.autoFarm and not Runtime.farming then
            task.spawn(doFarmLoop)
        end
    end)
end)

local function isCarryingEgg(otherChar)
    local char = otherChar or getChar()
    if not char then return false end
    for _, obj in ipairs(char:GetChildren()) do
        if obj:IsA("Tool") and obj.Name:lower():find("egg") then return true end
    end
    for _, obj in ipairs(char:GetDescendants()) do
        if (obj:IsA("BasePart") or obj:IsA("MeshPart") or obj:IsA("Model")) and obj.Parent == char then
            local n = obj.Name:lower()
            if n:find("egg") and not n:find("zone") and not n:find("root") and not n:find("prompt") then
                return true
            end
        end
    end
    if char:GetAttribute("CarryingEgg") or char:GetAttribute("IsCarrying") or char:GetAttribute("HoldingEgg") then
        return true
    end
    return false
end

-- ============================================================
-- [INFINITE YIELD-STYLE TPWALK (WASD & MANUAL ENGINE)]
-- ============================================================
local TPWalkConn = nil
local function setupTPWalkEngine()
    if TPWalkConn then
        TPWalkConn:Disconnect()
        TPWalkConn = nil
    end

    TPWalkConn = S.RunService.Heartbeat:Connect(function(delta)
        local char = LP.Character
        local humanoid = char and char:FindFirstChildWhichIsA("Humanoid")
        -- Berjalan via TranslateBy saat WASD ditekan dan tidak sedang auto-farm pathing
        if char and humanoid and humanoid.Parent and not Runtime.isAutoWalking then
            if humanoid.MoveDirection.Magnitude > 0 then
                char:TranslateBy(humanoid.MoveDirection * Cfg.walkSpeed * delta * 10)
            end
        end
    end)
    table.insert(ScriptConnections, TPWalkConn)
end
setupTPWalkEngine()

-- ============================================================
-- [TREADMILL CONTROLLER & ANTI-STUCK ENGINE]
-- ============================================================
local function isPlayerOnTreadmill()
    local root = getRoot()
    if not root then return false end
    local plots = S.Workspace:FindFirstChild("Plots")
    if plots then
        for _, p in ipairs(plots:GetChildren()) do
            local tb = p:FindFirstChild("TreadmillBottom")
            if tb and (root.Position - tb.Position).Magnitude <= 12 then
                return true, tb
            end
        end
    end
    return false
end

local function releaseTreadmill()
    pcall(function()
        local rf = S.ReplicatedStorage.Packages.Networking:FindFirstChild("RF/Treadmill/AskDoff")
        if rf then rf:InvokeServer() end
    end)
    pcall(function()
        local tc = require(LP.PlayerScripts.Game.Plots.TreadmillCharacterPresentationController)
        if tc and tc.Stop then tc.Stop() end
    end)
    local root = getRoot()
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if hum then pcall(function() hum.Jump = true end) end
    if root then root.AssemblyLinearVelocity = Vector3.new(0, 20, 0) end
end

-- ============================================================
-- [FARM MOVEMENT ENGINE: PURE TRANSLATEBY TPWALK (IY IDENTICAL)]
-- ============================================================

-- Helper aman untuk memastikan tool/egg lama tidak tetap di Character.
-- Hanya dipakai saat cycle BARU / perjalanan MENUJU egg.
local function forceUnequipTools()
    local char = LP.Character
    if not char then return false end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return false end

    local ok = pcall(function()
        hum:UnequipTools()
    end)

    return ok
end

-- keepUnequipped:
-- false/nil = TPWalk normal (contoh: membawa egg pulang Safezone)
-- true      = selama perjalanan, paksa Character tetap tanpa tool
local function tpWalk(targetPos, stopDist, keepUnequipped, shouldContinue)
    stopDist = stopDist or 4
    Runtime.isAutoWalking = true

    local timeout = tick() + 25
    local lastUnequip = 0

    -- Safety pertama sebelum mulai bergerak ke target egg.
    if keepUnequipped then
        forceUnequipTools()
        lastUnequip = tick()
    end

    while tick() < timeout and (Cfg.autoFarm or PlotCfg.autoPlace) do
        -- Optional cancellation predicate. Existing Farm callers are unchanged.
        if shouldContinue then
            local okCheck, keepGoing = pcall(shouldContinue)
            if not okCheck or not keepGoing then
                Runtime.isAutoWalking = false
                local cancelRoot = getRoot()
                if cancelRoot then
                    pcall(function()
                        cancelRoot.AssemblyLinearVelocity = Vector3.zero
                        cancelRoot.AssemblyAngularVelocity = Vector3.zero
                    end)
                end
                return false
            end
        end

        local char = getChar()
        local root = getRoot()
        local hum  = getHumanoid()

        if not char or not root or not hum or hum.Health <= 0 then
            task.wait(0.05)
            char, root, hum = ensureCharacter(5)

            if not char or not root or not hum then
                Runtime.isAutoWalking = false
                return false
            end
        end

        -- ========================================================
        -- DOUBLE SAFETY UNEQUIP
        -- HANYA ketika menuju egg baru.
        -- Tidak aktif saat membawa egg pulang ke Safezone.
        -- ========================================================
        if keepUnequipped and (tick() - lastUnequip >= 0.10) then
            forceUnequipTools()
            lastUnequip = tick()
        end

        if isPlayerOnTreadmill and isPlayerOnTreadmill() then
            releaseTreadmill()
        end

        local currentPos = root.Position
        local dist = (currentPos - targetPos).Magnitude

        if dist <= stopDist then
            root.AssemblyLinearVelocity = Vector3.zero

            -- Safety terakhir tepat saat sampai target egg.
            if keepUnequipped then
                forceUnequipTools()
            end

            Runtime.isAutoWalking = false
            return true
        end

        local dt = S.RunService.Heartbeat:Wait()
        local dir = (targetPos - currentPos).Unit

        -- Rumus identik Infinite Yield: dir * Cfg.walkSpeed * dt * 10
        local step = Cfg.walkSpeed * dt * 10
        local moveAmt = math.min(step, dist)

        char:TranslateBy(dir * moveAmt)
    end

    Runtime.isAutoWalking = false

    if keepUnequipped then
        forceUnequipTools()
    end

    local root = getRoot()
    return (root and (root.Position - targetPos).Magnitude <= stopDist + 2) or false
end

-- ============================================================
-- [ULTRA FPS BOOST ENGINE]
-- ============================================================
local UltraFpsState = {
    enabled = false,
    conn = nil,
}

local function applyUltraFps(enabled)
    UltraFpsState.enabled = enabled
    if enabled then
        local function processObject(p)
            if not p then return end
            if p:IsA("Decal") or p:IsA("Texture") then
                pcall(function() p.Transparency = 1 end)
            elseif p:IsA("BasePart") then
                local anc = p.Parent
                local isProtected = false
                while anc do
                    if anc == LP.Character
                        or anc:IsA("Tool")
                        or anc.Name == "Plots"
                        or anc.Name == "AreaEggSlotsClient"
                        or anc.Name == "__OBJECTS"
                        or anc.Name == "Characters"
                        or (typeof(anc.FindFirstChildOfClass) == "function" and anc:FindFirstChildOfClass("Humanoid"))
                    then
                        isProtected = true
                        break
                    end
                    anc = anc.Parent
                end
                if not isProtected then
                    pcall(function()
                        p.CastShadow = false
                        p.Transparency = 1
                    end)
                end
            end
        end

        for _, d in ipairs(S.Workspace:GetDescendants()) do
            processObject(d)
        end

        if not UltraFpsState.conn then
            UltraFpsState.conn = S.Workspace.DescendantAdded:Connect(function(d)
                if not UltraFpsState.enabled then return end
                task.wait(0.05)
                pcall(processObject, d)
            end)
            table.insert(ScriptConnections, UltraFpsState.conn)
        end
    else
        if UltraFpsState.conn then
            UltraFpsState.conn:Disconnect()
            UltraFpsState.conn = nil
        end
    end
end

-- ============================================================
-- [BACKPACK PET SPEED DISPLAY ENGINE]
-- ============================================================
local function updateBackpackSpeedDisplay()
    pcall(function()
        local pg = LP:FindFirstChild("PlayerGui")
        local bg = pg and pg:FindFirstChild("BackpackGui")
        if not bg then return end
        local inv = bg:FindFirstChild("Backpack") and bg.Backpack:FindFirstChild("Main") and bg.Backpack.Main:FindFirstChild("Inventory")
        if not inv then return end

        local rs = S.ReplicatedStorage
        local Assets = nil
        pcall(function() Assets = require(rs.Data.Assets) end)
        local assetsDir = Assets and (Assets.Directory or Assets)
        local mut = nil
        pcall(function() mut = require(rs.Shared.Modules.Mutations) end)
        local FormatShort = nil
        pcall(function() FormatShort = require(rs.UserGenerated.Strings.FormatShort) end)
        if not FormatShort then
            FormatShort = function(n)
                if n >= 1e9 then return string.format("%.1fB", n/1e9)
                elseif n >= 1e6 then return string.format("%.1fM", n/1e6)
                elseif n >= 1e3 then return string.format("%.1fk", n/1e3)
                else return tostring(math.floor(n)) end
            end
        end

        local function getToolSpeed(tool)
            local attrs = tool:GetAttributes()
            local cat = attrs.Category or attrs.DisplayName or tool.Name:match("^([%a%s%-]+)")
            local assetData = assetsDir and assetsDir[cat]
            if not assetData and assetsDir then
                for k, v in pairs(assetsDir) do
                    if k:lower() == tostring(cat):lower() or (v.DisplayName and v.DisplayName:lower() == tostring(cat):lower()) then
                        assetData = v
                        break
                    end
                end
            end
            local baseRate = (assetData and assetData.EarningRate) or 0
            local mult = 1
            local mutName = attrs.BaseMutation or attrs.Mutations
            if mut and mutName and mutName ~= "" and mutName ~= "None" then
                local ok, m = pcall(function() return mut.EarningsFor({mutName}) end)
                if ok and type(m) == "number" then mult = m end
            end
            return baseRate * mult
        end

        -- 1. Total Speed Header
        local totalSpeed = 0
        local bp = LP:FindFirstChild("Backpack")
        if bp then
            for _, tool in ipairs(bp:GetChildren()) do
                if tool:IsA("Tool") and tool:GetAttribute("ItemType") == "Asset" then
                    totalSpeed = totalSpeed + getToolSpeed(tool)
                end
            end
        end

        local totalLbl = inv:FindFirstChild("DHub_TotalSpeed")
        if not totalLbl then
            totalLbl = Instance.new("TextLabel")
            totalLbl.Name = "DHub_TotalSpeed"
            totalLbl.Parent = inv
            totalLbl.BackgroundTransparency = 1
            totalLbl.Position = UDim2.new(0.35, 0, 0.02, 0)
            totalLbl.Size = UDim2.new(0.35, 0, 0.08, 0)
            totalLbl.Font = Enum.Font.GothamBold
            totalLbl.TextSize = 13
            totalLbl.TextColor3 = Color3.fromRGB(80, 255, 120)
            totalLbl.TextXAlignment = Enum.TextXAlignment.Left
        end
        totalLbl.Text = string.format("[Total Speed: +%s/s]", tostring(FormatShort(totalSpeed)):upper())

        -- 2. Card Speed Badges (Top-Right)
        local sf = inv:FindFirstChild("ScrollingFrame")
        if sf then
            for _, btn in ipairs(sf:GetChildren()) do
                if btn:IsA("TextButton") and btn.Name ~= "Template" then
                    local toolNameLbl = btn:FindFirstChild("ToolName", true)
                    if toolNameLbl and toolNameLbl.Text ~= "" then
                        local rawText = toolNameLbl.Text
                        local cleanName = rawText:gsub("%s*%([%d%.,]+%a*%)", ""):gsub("^%s+", ""):gsub("%s+$", "")

                        local mutMult = 1
                        local baseCat = cleanName
                        if mut and mut.IdSet then
                            for mId, _ in pairs(mut.IdSet) do
                                if cleanName:sub(1, #mId) == mId then
                                    local ok, m = pcall(function() return mut.EarningsFor({mId}) end)
                                    if ok and type(m) == "number" then mutMult = m end
                                    baseCat = cleanName:sub(#mId + 2):gsub("^%s+", "")
                                    break
                                end
                            end
                        end

                        local assetData = assetsDir and assetsDir[baseCat]
                        if not assetData and assetsDir then
                            for k, v in pairs(assetsDir) do
                                if k:lower() == baseCat:lower() or (v.DisplayName and v.DisplayName:lower() == baseCat:lower()) then
                                    assetData = v
                                    break
                                end
                            end
                        end
                        local rate = (assetData and assetData.EarningRate) or 0
                        local petSpeed = rate * mutMult

                        local cardSpdLbl = btn:FindFirstChild("DHub_CardSpeed")
                        if not cardSpdLbl then
                            cardSpdLbl = Instance.new("TextLabel")
                            cardSpdLbl.Name = "DHub_CardSpeed"
                            cardSpdLbl.Parent = btn
                        end
                        cardSpdLbl.ZIndex = 1000
                        cardSpdLbl.BackgroundColor3 = Color3.fromRGB(15, 12, 28)
                        cardSpdLbl.BackgroundTransparency = 0.25
                        cardSpdLbl.AnchorPoint = Vector2.new(1, 0)
                        cardSpdLbl.Position = UDim2.new(1, -4, 0, 4)
                        cardSpdLbl.Size = UDim2.new(0, 56, 0, 16)
                        cardSpdLbl.Font = Enum.Font.GothamBold
                        cardSpdLbl.TextSize = 10
                        cardSpdLbl.TextColor3 = Color3.fromRGB(80, 255, 120)
                        cardSpdLbl.TextXAlignment = Enum.TextXAlignment.Center

                        local c2 = cardSpdLbl:FindFirstChildOfClass("UICorner") or Instance.new("UICorner", cardSpdLbl)
                        c2.CornerRadius = UDim.new(0, 4)

                        local stk = cardSpdLbl:FindFirstChildOfClass("UIStroke") or Instance.new("UIStroke", cardSpdLbl)
                        stk.Color = Color3.fromRGB(60, 40, 90)
                        stk.Thickness = 1

                        cardSpdLbl.Text = "+" .. tostring(FormatShort(petSpeed)):upper() .. "/s"
                    end
                end
            end
        end
    end)
end

-- Listener backpack speed
