        end)
    end)
    makeLabel(ProfileBar, LP.DisplayName, UDim2.new(1,-54,0,16), UDim2.new(0,50,0.5,-16), Enum.Font.GothamBold, 10, C.TEXT_1)
    makeLabel(ProfileBar, "D-Hub V2.1",     UDim2.new(1,-54,0,12), UDim2.new(0,50,0.5,2),   Enum.Font.Gotham,     9,  C.ACCENT)

    local ContentArea = makeFrame(Body, UDim2.new(1,-145,1,0), UDim2.new(0,145,0,0))
    ContentArea.BackgroundTransparency = 1

    local pages   = {}
    local navBtns = {}

    local function makePage(name)
        local page = Instance.new("ScrollingFrame", ContentArea)
        page.Name = name; page.Size = UDim2.new(1,0,1,0)
        page.BackgroundTransparency = 1; page.BorderSizePixel = 0
        page.ScrollBarThickness = 3; page.ScrollBarImageColor3 = C.DIVIDER
        page.Visible = (name == "Auto")
        page.CanvasSize = UDim2.new(0,0,0,1200)
        local layout = listLayout(page, 8)
        padding(page, 14, 14, 14, 14)
        layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            page.CanvasSize = UDim2.new(0,0,0,math.max(layout.AbsoluteContentSize.Y+35, 600))
        end)
        pages[name] = page
        return page
    end

    local function switchTab(name)
        if UI.closeActiveDropdown then UI.closeActiveDropdown() end
        for n, p in pairs(pages) do
            local on = (n == name)
            p.Visible = on
            if on then
                local layout = p:FindFirstChildOfClass("UIListLayout")
                if layout then
                    local absY = layout.AbsoluteContentSize.Y
                    p.CanvasSize = UDim2.new(0, 0, 0, math.max(absY + 35, 600))
                end
            end
        end
        for n, d in pairs(navBtns) do
            local on = (n == name)
            TS:Create(d.btn, TweenInfo.new(0.18), {BackgroundColor3 = on and C.ELEVATED or C.SURFACE}):Play()
            TS:Create(d.ind, TweenInfo.new(0.18), {BackgroundTransparency = on and 0 or 1}):Play()
            d.lbl.TextColor3 = on and C.TEXT_1 or C.TEXT_2
        end
    end

    local function makeNavBtn(name)
        local btn = makeButton(TabScroll, "", UDim2.new(1,-2,0,34), nil, C.SURFACE); corner(btn, 6)
        local ind = makeFrame(btn, UDim2.new(0,3,0,16), UDim2.new(0,0,0.5,-8), C.ACCENT); corner(ind, 2)
        ind.BackgroundTransparency = (name == "Auto") and 0 or 1
        local lbl = makeLabel(btn, name, UDim2.new(1,-16,1,0), UDim2.new(0,12,0,0), Enum.Font.GothamMedium, 11, (name == "Auto") and C.TEXT_1 or C.TEXT_2)
        btn.MouseButton1Click:Connect(function() switchTab(name) end)
        navBtns[name] = {btn=btn, ind=ind, lbl=lbl}
    end

    local TAB_LIST = {"Auto", "Plot", "Shop", "Misc", "Info"}
    for _, t in ipairs(TAB_LIST) do makeNavBtn(t); makePage(t) end

    -- ============ TAB: AUTO ============
    local P = pages["Auto"]
    BuatSection(P, "Egg Farm")

    local statusRow = makeFrame(P, UDim2.new(1,0,0,32), nil, C.SURFACE); corner(statusRow); stroke(statusRow, C.BORDER)
    local statusLbl = makeLabel(statusRow, "Status: Idle  |  Steals: 0", UDim2.new(1,-14,1,0), UDim2.new(0,10,0,0), Enum.Font.Gotham, 11, C.ACCENT)
    Runtime.StatusLbl = statusLbl

    BuatMultiSelect(P, "Select Area", ZONE_NAMES, Cfg.selectedAreas, function(tbl)
        Cfg.selectedAreas = tbl; saveConfig()
    end)

    BuatMultiSelect(P, "Select Rarity", RARITIES, Cfg.selectedRarities, function(tbl)
        Cfg.selectedRarities = tbl; saveConfig()
    end)

    BuatInput(P, "Min Weight", "0 = All", tostring(Cfg.minWeight), function(v)
        Cfg.minWeight = math.max(0, tonumber(v) or 0); saveConfig()
    end)

    BuatDropdown(P, "Farm Priority", {"Nearest", "Hugest", "Rarest"}, Cfg.farmPriority, function(v)
        Cfg.farmPriority = v or "Nearest"; saveConfig()
    end)

    BuatToggle(P, "Instant Steal (0s Prompt)", Cfg.instantSteal, function(v)
        Cfg.instantSteal = v
        if v then applyInstantToAll() end
        saveConfig()
    end)

    BuatToggle(P, "Auto Farm Eggs", Cfg.autoFarm, function(v)
        Cfg.autoFarm = v

        -- Farm/Plot may never own movement at the same time.
        PlotRuntime.placeGeneration = PlotRuntime.placeGeneration + 1
        PlotRuntime.placeOwner = nil

        if v and not Runtime.farming then
            task.spawn(doFarmLoop)
        elseif not v and PlotCfg.autoPlace and not PlotRuntime.placing then
            -- Auto Plot stays enabled: resume as a fresh standalone worker.
            task.spawn(doPlotPlaceLoop)
        end

        saveConfig()
    end)

    BuatToggle(P, "Anti Boss", Cfg.antiBoss, function(v)
        Cfg.antiBoss = v

        if not v then
            stopAntiBossSpamTeleport()
        end

        saveConfig()
    end)

    BuatToggle(P, "Auto Treadmill (When Waiting)", Cfg.autoTreadmill, function(v)
        Cfg.autoTreadmill = v
        if not v and isPlayerOnTreadmill() then releaseTreadmill() end
        saveConfig()
    end)

    BuatSection(P, "Speed Settings (Infinite Yield Engine)")

    BuatSlider(P, "TPWalk Speed", 1, 150, Cfg.walkSpeed, function(v)
        Cfg.walkSpeed = v
        saveConfig()
    end)

    BuatActionBtn(P, "Reset Steal Counter", C.SURFACE, function()
        Runtime.steals = 0; UpdateStatus(Runtime.statusText)
        Notify("Counter reset", 2)
    end)

    BuatActionBtn(P, "Force Re-Scan", C.SURFACE, function()
        ScanCache.lastScan = 0
        Notify("Cache cleared, next cycle re-scans", 2)
    end)

    -- ============ TAB: PLOT ============
    local PP = pages["Plot"]
    BuatSection(PP, "Plot Manager")

    local plotStatusRow = makeFrame(PP, UDim2.new(1,0,0,32), nil, C.SURFACE)
    corner(plotStatusRow); stroke(plotStatusRow, C.BORDER)
    local plotStatusLbl = makeLabel(plotStatusRow,
        "Plot: Idle  |  Placed: 0",
        UDim2.new(1,-14,1,0), UDim2.new(0,10,0,0),
        Enum.Font.Gotham, 11, C.ACCENT)
    PlotRuntime.StatusLbl2 = plotStatusLbl

    BuatSection(PP, "Place Settings")

    BuatMultiSelect(PP, "Rarity To Place", RARITIES, PlotCfg.selectedRarities, function(tbl)
        PlotCfg.selectedRarities = tbl; saveConfig()
    end)

    BuatInput(PP, "Min Weight To Place", "0 = place all", tostring(PlotCfg.minWeight), function(v)
        PlotCfg.minWeight = math.max(0, tonumber(v) or 0); saveConfig()
    end)

    BuatSection(PP, "Automation")

    BuatToggle(PP, "Auto Place Eggs", PlotCfg.autoPlace, function(v)
        PlotCfg.autoPlace = v

        -- Hard-cancel old Plot execution on every state change.
        PlotRuntime.placeGeneration = PlotRuntime.placeGeneration + 1
        PlotRuntime.placeOwner = nil

        if v and not PlotRuntime.placing and not Cfg.autoFarm then
            task.spawn(doPlotPlaceLoop)
        elseif not v then
            UpdatePlotStatus("Idle")
        end

        saveConfig()
    end)

    BuatToggle(PP, "Auto Hatch Eggs", PlotCfg.autoHatch, function(v)
        PlotCfg.autoHatch = v
        if v and not PlotRuntime.hatching then task.spawn(doHatchLoop) end
        saveConfig()
    end)

    BuatSection(PP, "Actions")

    BuatActionBtn(PP, "Place Eggs Now", C.ACCENT_D, function()
        if Cfg.autoFarm then
            Notify("Stop Auto Farm before manual Plot placement.", 3)
            return
        end

        PlotRuntime.placeGeneration = PlotRuntime.placeGeneration + 1
        local manualGeneration = PlotRuntime.placeGeneration
        local ok = doPlotPlaceOnce("manual", manualGeneration)

        Notify(ok and "Placed eggs successfully!" or "Could not place (full / none)", 3)
    end)

    BuatActionBtn(PP, "Reset Placed Counter", C.SURFACE, function()
        PlotRuntime.placedCount = 0; UpdatePlotStatus(PlotRuntime.statusText)
        Notify("Plot counter reset", 2)
    end)

    -- ============ TAB: SHOP ============
    local PS = pages["Shop"]

    BuatSection(PS, "Auto Sell Eggs")

    -- sellEggRarities: defaultNone=true → default "None"
    BuatMultiSelect(PS, "Egg Rarity to Sell", SELL_RARITIES, ShopCfg.sellEggRarities, function(tbl)
        ShopCfg.sellEggRarities = tbl; saveConfig()
    end, true) -- defaultNone = true

    BuatSection(PS, "Auto Sell Pets")

    -- sellPetRarities: defaultNone=true → default "None"
    BuatMultiSelect(PS, "Pet Rarity to Sell", SELL_RARITIES, ShopCfg.sellPetRarities, function(tbl)
        ShopCfg.sellPetRarities = tbl; saveConfig()
    end, true) -- defaultNone = true

    BuatToggle(PS, "Auto Sell (aktif saat farm)", ShopCfg.autoSellAll, function(v)
        ShopCfg.autoSellAll = v; saveConfig()
    end)

    BuatActionBtn(PS, "Sell Now", C.ACCENT_D, function()
        task.spawn(doSellCycle)
        Notify("Sell cycle started!", 2)
    end)

    BuatSection(PS, "Auto Upgrade")

    BuatToggle(PS, "Auto Upgrade Plot", ShopCfg.autoUpgradePlot, function(v)
        ShopCfg.autoUpgradePlot = v; saveConfig()
    end)

    BuatToggle(PS, "Auto Upgrade Treadmill", ShopCfg.autoUpgradeTread, function(v)
        ShopCfg.autoUpgradeTread = v; saveConfig()
    end)

    BuatSection(PS, "Auto Fuse Pets")

    local fuseOptions, _ = getFusePetOptions()
    BuatDropdown(PS, "Select Pet To Fuse", fuseOptions, ShopCfg.selectedPetFuse ~= "" and ShopCfg.selectedPetFuse or "None", function(v)
        ShopCfg.selectedPetFuse = v or "None"; saveConfig()
    end)

    BuatToggle(PS, "Fuse Pet", ShopCfg.autoFuse, function(v)
        ShopCfg.autoFuse = v; saveConfig()
        if v then
            local ok, msg = doFuseOnce()
            Notify(msg or (ok and "Fusing..." or "Fuse failed"), 3)
        end
    end)

    -- ============ TAB: MISC ============
    local PM = pages["Misc"]

    BuatSection(PM, "Performance")

    BuatToggle(PM, "FPS Boost", MiscCfg.fpsBoost, function(v)
        MiscCfg.fpsBoost = v
        applyFpsBoost(v)
        saveConfig()
    end)

    BuatToggle(PM, "Ultra FPS Boost (Invisible Parts)", MiscCfg.ultraFps, function(v)
        MiscCfg.ultraFps = v
        applyUltraFps(v)
        saveConfig()
    end)

    BuatSection(PM, "Server Hop")

    BuatSlider(PM, "Select Delay Hop (Minutes)", 1, 120, MiscCfg.hopDelay or 30, function(v)
        MiscCfg.hopDelay = v; saveConfig()
    end)

    BuatDropdown(PM, "Hop Method", {"Small Server", "Random Server"}, MiscCfg.hopMethod or "Small Server", function(v)
        MiscCfg.hopMethod = v or "Small Server"; saveConfig()
    end)

    BuatToggle(PM, "Auto Hop Server", MiscCfg.autoHop, function(v)
        MiscCfg.autoHop = v
        if v then HopState.lastHopCheck = tick() end
        saveConfig()
    end)

    BuatActionBtn(PM, "Hop Now", C.ACCENT, function()
        Notify("Hopping to another server...", 3)
        task.delay(1, function()
            executeServerHop(MiscCfg.hopMethod)
        end)
    end)

    -- ============ TAB: INFO ============
    local PI = pages["Info"]
    BuatSection(PI, "Script Info")
    local function infoLabel(text)
        local row = makeFrame(PI, UDim2.new(1,0,0,30), nil, C.SURFACE); corner(row); stroke(row, C.BORDER)
        makeLabel(row, text, UDim2.new(1,-14,1,0), UDim2.new(0,10,0,0), Enum.Font.Gotham, 10, C.TEXT_2)
    end
    infoLabel("D-Hub Steal An Egg V2.1")
    infoLabel("TPWalk: Infinite Yield TranslateBy Engine")
    infoLabel("Sell Egg: WearEggTool → SellPet (per-item)")
    infoLabel("Sell Pet: SellEveryPet (batch, non-equipped)")
    infoLabel("PlaceId: " .. PLACE_ID)
    infoLabel("Player: " .. LP.Name .. " (" .. LP.UserId .. ")")
    infoLabel("Safezone: 512, 68, -363")
    infoLabel("Scan Chunk: " .. SCAN_CHUNK_SIZE .. " eggs/frame")
    infoLabel("Plot Grid: " .. PLOT_GRID_COLS .. "x" .. PLOT_GRID_ROWS .. " @ " .. PLOT_GRID_SPACING .. " spacing")

    switchTab("Auto")
    task.defer(function()
        task.wait(0.05)
        switchTab("Auto")
    end)
end

-- [19] MAIN LAUNCH
local function launch()
    buildUI()

    task.spawn(function()
        task.wait(0.3)
        ensureCharacter(5)

        if Cfg.instantSteal then applyInstantToAll() end

        if Cfg.autoFarm and not Runtime.farming then
            task.spawn(doFarmLoop)
        elseif PlotCfg.autoPlace and not PlotRuntime.placing and not Cfg.autoFarm then
            task.spawn(doPlotPlaceLoop)
        end

        if PlotCfg.autoHatch and not PlotRuntime.hatching then
            task.spawn(doHatchLoop)
        end

        if MiscCfg.fpsBoost then applyFpsBoost(true) end
        if MiscCfg.ultraFps then applyUltraFps(true) end
        if ShopCfg.autoSellAll then task.spawn(function() task.wait(0.5); doSellCycle() end) end
        if ShopCfg.autoFuse then task.spawn(function() task.wait(0.5); doFuseOnce() end) end
    end)

    Notify("D-Hub SAE V2.1 Loaded!", 3)
end

local key = getEnvKey()
if not key or key=="" then
    pcall(function() if isfile and isfile(KEY_PATH) then key = readfile(KEY_PATH) end end)
end
if isDevMode() then
    launch()
else
    if checkKey(key) then
        pcall(function() writefile(KEY_PATH, key) end)
        launch()
    else
        pcall(function() LP:Kick("D-Hub | Invalid Key. Get key: " .. GET_KEY_URL) end)
    end
end
